"""Small saved-default editor inside the existing Studio generation form."""
ROUTING_CSS = '''.script-routing-settings{border:1px solid var(--line);border-radius:9px;padding:12px;margin:0 0 16px}.script-routing-settings summary{font-weight:700;cursor:pointer}.script-routing-settings select{width:100%;min-width:0;max-width:100%}.script-routing-settings .actions{display:flex;flex-wrap:wrap;margin-top:12px}.script-routing-settings p{overflow-wrap:anywhere}'''

ROUTING_SCRIPT = r'''
const routingPanel=document.createElement('details');routingPanel.className='script-routing-settings';routingPanel.id='scriptRoutingSettings';
const routingSummary=document.createElement('summary');routingSummary.textContent='Script routing defaults — loading';routingPanel.append(routingSummary);
const routingHelp=document.createElement('p');routingHelp.className='sub';routingHelp.textContent='Saved defaults apply to new manual, batch and scheduled jobs. Existing jobs keep their policy.';routingPanel.append(routingHelp);
function routingSelect(labelText,id){const label=document.createElement('label');label.textContent=labelText;const select=document.createElement('select');select.id=id;select.disabled=true;label.append(select);routingPanel.append(label);return select;}
const routingMode=routingSelect('Mode','scriptRoutingMode'),routingPreferred=routingSelect('Default writer / automatic primary','scriptRoutingPreferred');
const routingActions=document.createElement('div');routingActions.className='actions';
const routingSave=document.createElement('button');routingSave.type='button';routingSave.id='saveScriptRouting';routingSave.textContent='Save routing defaults';routingSave.disabled=true;
const routingReload=document.createElement('button');routingReload.type='button';routingReload.className='secondary';routingReload.textContent='Reload saved policy';routingReload.id='reloadScriptRouting';routingActions.append(routingSave,routingReload);routingPanel.append(routingActions);
const routingStatus=document.createElement('p');routingStatus.className='sub';routingStatus.id='scriptRoutingStatus';routingStatus.setAttribute('role','status');routingStatus.setAttribute('aria-live','polite');routingStatus.textContent='Loading saved routing policy…';routingPanel.append(routingStatus);form.insertBefore(routingPanel,ownerLabel);
const routingLabels={claude_only:'Claude only',codex_only:'Codex only',automatic:'Automatic fallback'};
let routingPolicy=null,routingWriters=[],routingReady=false,routingBusy=false,routingDirty=false;
function routingOptions(select,options){select.replaceChildren();for(const value of options)select.append(Object.assign(document.createElement('option'),{value:value.id,textContent:value.label||routingLabels[value.id],disabled:!value.enabled}));}
function preferredOptions(){const previous=routingPreferred.value;const choices=routingWriters.filter(w=>routingMode.value==='codex_only'?w.id==='gpt-sol':routingMode.value==='claude_only'?w.id!=='gpt-sol':true);routingOptions(routingPreferred,choices);routingPreferred.value=choices.some(w=>w.id===previous&&w.enabled)?previous:(choices.find(w=>w.enabled)?.id||'');}
function routingSync(){const pending=routingBusy||!!window.scriptRoutingCreationPending;routingMode.disabled=pending||!routingPolicy;routingPreferred.disabled=pending||!routingPolicy;routingSave.disabled=pending||!routingPolicy||!routingPreferred.value;routingReload.disabled=pending;ownerSelect.disabled=!routingReady||pending||routingDirty;const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=!routingReady||pending||routingDirty;}
function routingCanSubmit(){if(!routingReady||routingBusy||routingDirty||window.scriptRoutingCreationPending){routingPanel.open=true;routingStatus.textContent=window.scriptRoutingCreationPending?'Wait for the current video submission to finish.':routingDirty?'Save routing changes or reload the saved policy before generating.':routingBusy?'Wait for the routing policy request to finish.':'Routing policy unavailable. Reload it or save an enabled mode.';return false;}return true;}
window.scriptRoutingCanSubmit=routingCanSubmit;window.syncScriptRoutingControls=routingSync;
window.restoreScriptRouting=()=>{if(!routingPolicy)return;routingMode.value=routingPolicy.mode||(routingPolicy.preferred_model==='gpt-sol'?'codex_only':'claude_only');preferredOptions();routingPreferred.value=routingPolicy.preferred_model;ownerSelect.value=routingPolicy.preferred_model;routingDirty=false;routingSync();};
form.addEventListener('submit',event=>{if(!routingCanSubmit()){event.preventDefault();event.stopImmediatePropagation();}},true);
async function loadRouting(){routingBusy=true;routingSync();try{const [policyResponse,profileResponse]=await Promise.all([fetch('/api/script-routing'),fetch('/api/content-profiles')]);if(!policyResponse.ok||!profileResponse.ok)throw Error('Could not load routing policy.');const policy=await policyResponse.json(),profiles=await profileResponse.json();routingPolicy=policy;routingWriters=profiles.all_script_models||profiles.script_models;routingOptions(ownerSelect,profiles.script_models.filter(w=>w.enabled));ownerSelect.value=profiles.default_script_model;routingOptions(routingMode,policy.modes);routingMode.value=policy.mode||(policy.preferred_model==='gpt-sol'?'codex_only':'claude_only');preferredOptions();routingPreferred.value=policy.preferred_model;routingReady=policy.modes.some(m=>m.id===routingMode.value&&m.enabled)&&profiles.script_models.some(w=>w.enabled);routingDirty=false;routingSummary.textContent='Script routing defaults · '+(policy.mode?routingLabels[policy.mode]:'not saved');routingStatus.textContent=!routingReady?'Saved mode is unavailable. Choose an enabled mode and save.':policy.mode?`Saved: ${routingLabels[policy.mode]} · ${policy.preferred_model}. Saved by ${policy.actor||'operator'}${policy.saved_at?' · '+new Date(policy.saved_at).toLocaleString():''}. Future jobs only.`:'No policy saved yet. Existing writer defaults apply until you save a mode.';}finally{routingBusy=false;routingSync();}}
routingMode.onchange=()=>{preferredOptions();routingDirty=true;routingSummary.textContent='Script routing defaults · unsaved changes';routingStatus.textContent='Unsaved changes. Save to apply them to future jobs.';routingSync();};
routingPreferred.onchange=()=>{routingDirty=true;routingStatus.textContent='Unsaved changes. Save to apply them to future jobs.';routingSync();};
routingReload.onclick=async()=>{try{await loadRouting();}catch(error){routingReady=false;routingStatus.textContent=error.message+' Reload to retry.';routingSync();}};
routingSave.onclick=async()=>{if(routingBusy||!routingPolicy)return;routingBusy=true;routingStatus.textContent='Saving routing defaults…';routingSync();let confirmed=false,rejected=false;try{const csrf=decodeURIComponent((document.cookie.match(/(?:^|; )tubeforge_csrf=([^;]+)/)||[])[1]||'');const response=await fetch('/api/script-routing',{method:'PUT',headers:{'content-type':'application/json','x-csrf-token':csrf},body:JSON.stringify({mode:routingMode.value,preferred_model:routingPreferred.value,expected_revision:routingPolicy.revision})});const data=await response.json();if(!response.ok){rejected=true;throw Error(data.detail||'Could not save routing policy.');}confirmed=true;routingPolicy=data;await loadRouting();}catch(error){routingReady=false;routingStatus.textContent=(confirmed?'Policy saved, but writer options could not refresh. ':rejected?'Not saved. ':'Save not confirmed. ')+error.message+' Reload saved policy to retry.';}finally{routingBusy=false;routingSync();}};
loadRouting().catch(error=>{routingReady=false;routingStatus.textContent=error.message+' Reload saved policy to retry.';routingSync();});
'''

GENERATION_SUBMIT_SCRIPT = r'''document.querySelector('#createForm').onsubmit=async event=>{
 event.preventDefault();const submittedForm=event.currentTarget;
 if(window.scriptRoutingCanSubmit&&!window.scriptRoutingCanSubmit())return;
 window.scriptRoutingCreationPending=true;if(window.syncScriptRoutingControls)window.syncScriptRoutingControls();
 const d=new FormData(submittedForm);let sources=window.collectSources?window.collectSources():[];if(!sources.length)sources=null;
 const body={title:d.get('title'),notes:d.get('notes').split('\n').map(x=>x.trim()).filter(Boolean),angle:String(d.get('angle')||'').trim()||null,audience:String(d.get('audience')||'general').trim()||'general',sources,duration_seconds:Number(d.get('duration_seconds')),review_mode:d.get('review_mode'),captions_enabled:d.has('captions_enabled'),voice_id:d.get('voice_id')||null,show_source_credit:d.has('show_source_credit'),show_mascot:d.has('show_mascot'),channel_watermark:String(d.get('channel_watermark')||'').trim()||null};
 try{const response=await fetch('/api/videos',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw Error(await response.text());notice.textContent='Generation created. It will appear in the list shortly.';submittedForm.reset();if(window.restoreScriptRouting)window.restoreScriptRouting();submittedForm.querySelector('[name=duration_seconds]').value=60;submittedForm.querySelector('[name=captions_enabled]').checked=true;await refresh();}
 catch(error){notice.textContent='Generation not confirmed: '+error.message;}
 finally{window.scriptRoutingCreationPending=false;if(window.syncScriptRoutingControls)window.syncScriptRoutingControls();}
}'''
